#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const ll MOD = 998244353;
const int MAXN = 200000;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    
    vector<ll> inv(MAXN + 1);
    inv[1]=1;
    
    
    for(int i=2; i<= MAXN; i++) {
        inv[i]= MOD - (MOD / i)* inv[MOD % i] % MOD; }
        
        vector <ll> H(MAXN + 1,0);
        
        for(int i = 1; i <= MAXN; i++) { 
            H[i] = (H[i - 1] + inv[i]) % MOD; }
        
        int t;
        cin >> t;
        
        while(t--) {
            int n;
            cin >> n;
            
            ll ans = 0;
            for(int i=1; i <=n; i++) {
                ll x;
                cin >> x;
                x %= MOD;
                
                ll coeff = (H[i - 1] + H[n - i]) % MOD;
                ans = (ans + x* coeff) % MOD;
            }
            cout << ans << '\n';
        }
        return 0;
    }
